"use client";

import React, { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AccordionItem {
  id: string;
  title: string;
  subtitle?: string;
  content: React.ReactNode;
}

export interface AccordionProps {
  /** Array of collapsible items */
  items?: AccordionItem[];
  /** Allow multiple items to stay open simultaneously */
  allowMultiple?: boolean;
  /** Default open item IDs */
  defaultOpenIds?: string[];
  /** Additional container class names */
  className?: string;
}

const DEFAULT_ITEMS: AccordionItem[] = [
  {
    id: "item-1",
    title: "How do I install BoseUI components?",
    subtitle: "CLI & Manual Copy",
    content:
      "Run npx shadcn@latest add https://boseui.site/r/<slug>.json in your project terminal, or copy the TypeScript code directly from any component page.",
  },
  {
    id: "item-2",
    title: "Can I customize the Tailwind styles and animations?",
    subtitle: "100% Source Ownership",
    content:
      "Yes. Because the source file lives directly inside your src/components/ui/ folder, you can edit every Tailwind class, Framer Motion spring parameter, or TypeScript prop.",
  },
  {
    id: "item-3",
    title: "Does it support Light Mode, Dark Mode, and Reduced Motion?",
    subtitle: "Built-in Accessibility",
    content:
      "Every component is designed for high-contrast Light and Dark themes and automatically respects system prefers-reduced-motion settings.",
  },
];

export function Accordion({
  items = DEFAULT_ITEMS,
  allowMultiple = false,
  defaultOpenIds = ["item-1"],
  className,
}: AccordionProps) {
  const shouldReduceMotion = useReducedMotion();
  const [openIds, setOpenIds] = useState<string[]>(defaultOpenIds);

  const toggleItem = (id: string) => {
    setOpenIds((prev) => {
      const isOpen = prev.includes(id);
      if (allowMultiple) {
        return isOpen ? prev.filter((i) => i !== id) : [...prev, id];
      }
      return isOpen ? [] : [id];
    });
  };

  return (
    <div
      className={cn(
        "w-full max-w-md divide-y divide-neutral-200 overflow-hidden rounded-2xl border border-neutral-200 bg-white dark:divide-[#1F1F1F] dark:border-[#222222] dark:bg-[#0A0A0A]",
        className
      )}
    >
      {items.map((item) => {
        const isOpen = openIds.includes(item.id);
        return (
          <div key={item.id} className="flex flex-col">
            <button
              type="button"
              aria-expanded={isOpen}
              onClick={() => toggleItem(item.id)}
              className="flex w-full cursor-pointer items-center justify-between gap-4 px-5 py-4 text-left transition-colors hover:bg-neutral-50 dark:hover:bg-[#111111]"
            >
              <div className="min-w-0">
                <div className="text-xs font-semibold text-black dark:text-white sm:text-sm">
                  {item.title}
                </div>
                {item.subtitle && (
                  <div className="mt-0.5 font-mono text-[10px] uppercase tracking-wider text-neutral-400">
                    {item.subtitle}
                  </div>
                )}
              </div>

              <motion.span
                animate={{ rotate: isOpen ? 180 : 0 }}
                transition={
                  shouldReduceMotion
                    ? { duration: 0 }
                    : { type: "spring", stiffness: 360, damping: 26 }
                }
                className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md border border-neutral-200 text-neutral-500 dark:border-[#262626] dark:text-neutral-400"
              >
                <ChevronDown className="h-3.5 w-3.5" />
              </motion.span>
            </button>

            <AnimatePresence initial={false}>
              {isOpen && (
                <motion.div
                  initial={
                    shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }
                  }
                  animate={
                    shouldReduceMotion
                      ? { opacity: 1 }
                      : { height: "auto", opacity: 1 }
                  }
                  exit={
                    shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }
                  }
                  transition={{
                    duration: shouldReduceMotion ? 0 : 0.22,
                    ease: [0.22, 1, 0.36, 1],
                  }}
                  className="overflow-hidden"
                >
                  <div className="px-5 pb-4 text-xs leading-relaxed text-neutral-600 dark:text-neutral-400">
                    {item.content}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        );
      })}
    </div>
  );
}

export default Accordion;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import React, { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { Layers, ArrowUpRight, Sparkles, Terminal } from "lucide-react";
import { cn } from "@/lib/utils";

export interface StackCardItem {
  id: string;
  badge: string;
  title: string;
  metric: string;
  subtitle: string;
}

export interface AccordionStackCardsProps {
  /** Array of stack card items. Defaults to a 3-card telemetry deck. */
  items?: StackCardItem[];
  /** Spring stiffness coefficient for deck expansion and rotation. Default: 300 */
  stiffness?: number;
  /** Spring damping coefficient for deck expansion and rotation. Default: 25 */
  damping?: number;
  className?: string;
}

const DEFAULT_CARDS: StackCardItem[] = [
  {
    id: "spring-core",
    badge: "01 // PHYSICS ENGINE",
    title: "Hooke's Law Solver",
    metric: "120 Hz",
    subtitle: "Continuous velocity-preserving spring interpolation",
  },
  {
    id: "gpu-compositor",
    badge: "02 // COMPOSITOR",
    title: "Zero React Re-Renders",
    metric: "0.0 ms",
    subtitle: "Direct MotionValue & CSS mask-image projection",
  },
  {
    id: "shadcn-cli",
    badge: "03 // DISTRIBUTION",
    title: "Shadcn Registry v2",
    metric: "1-Click",
    subtitle: "Copy-paste source ownership with strict TypeScript",
  },
];

export function AccordionStackCards({
  items = DEFAULT_CARDS,
  stiffness = 300,
  damping = 25,
  className,
}: AccordionStackCardsProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const [deck, setDeck] = useState<StackCardItem[]>(items);
  const [isExpanded, setIsExpanded] = useState(false);

  const cycleFrontCard = () => {
    setDeck((prev) => {
      if (prev.length <= 1) return prev;
      const [first, ...rest] = prev;
      return [...rest, first!];
    });
  };

  return (
    <div
      onMouseEnter={() => setIsExpanded(true)}
      onMouseLeave={() => setIsExpanded(false)}
      className={cn(
        "relative flex min-h-[260px] w-full max-w-sm flex-col items-center justify-center py-4",
        className
      )}
    >
      <div className="relative h-[200px] w-full">
        {deck.map((card, index) => {
          const isFront = index === 0;
          const yOffset = isExpanded ? index * 54 : index * 12;
          const scale = isExpanded ? 1 : 1 - index * 0.05;
          const opacity = isExpanded ? 1 : 1 - index * 0.22;

          return (
            <motion.div
              key={card.id}
              layout
              role="button"
              tabIndex={0}
              aria-label={`${card.title} — ${card.subtitle}. Click to cycle stack.`}
              onFocus={() => setIsExpanded(true)}
              onBlur={() => setIsExpanded(false)}
              onClick={cycleFrontCard}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  cycleFrontCard();
                }
              }}
              animate={{
                y: yOffset,
                scale: shouldReduceMotion ? 1 : scale,
                opacity,
                zIndex: deck.length - index,
              }}
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : { type: "spring", stiffness, damping }
              }
              className={cn(
                "absolute inset-x-0 top-0 cursor-pointer select-none rounded-2xl border p-5 shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black dark:focus-visible:ring-white",
                isFront
                  ? "border-neutral-300 bg-white hover:border-black dark:border-[#2E2E2E] dark:bg-[#0D0D0D] dark:hover:border-white"
                  : "border-neutral-200 bg-neutral-50/95 dark:border-[#222222] dark:bg-[#141414]/95"
              )}
            >
              <div className="flex items-center justify-between gap-2">
                <span className="inline-flex items-center gap-1.5 font-mono text-[10px] font-semibold uppercase tracking-wider text-neutral-500 dark:text-neutral-400">
                  {index === 0 ? (
                    <Sparkles className="h-3 w-3 text-black dark:text-white" />
                  ) : index === 1 ? (
                    <Layers className="h-3 w-3" />
                  ) : (
                    <Terminal className="h-3 w-3" />
                  )}
                  {card.badge}
                </span>

                <span className="inline-flex items-center gap-1 rounded-full border border-neutral-200 bg-neutral-100 px-2 py-0.5 font-mono text-[10px] font-bold text-black dark:border-[#262626] dark:bg-[#1B1B1B] dark:text-white">
                  {card.metric}
                  <ArrowUpRight className="h-2.5 w-2.5" />
                </span>
              </div>

              <div className="mt-2.5 text-sm font-semibold text-black dark:text-white">
                {card.title}
              </div>
              <p className="mt-0.5 text-xs text-neutral-500 dark:text-neutral-400">
                {card.subtitle}
              </p>
            </motion.div>
          );
        })}
      </div>

      <div className="mt-4 text-center text-[11px] text-neutral-400 dark:text-neutral-500">
        Hover to fan out deck • Click any card to cycle stack
      </div>
    </div>
  );
}

export default AccordionStackCards;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import React, { useState, useId, useRef } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface TabItem {
  id: string;
  label: string;
  badge?: string | number;
  content: React.ReactNode;
}

export interface AnimatedTabsProps {
  /** Array of tab definitions */
  tabs?: TabItem[];
  /** Default active tab ID */
  defaultTabId?: string;
  /** Callback fired when active tab changes */
  onChange?: (tabId: string) => void;
  /** Additional container class names */
  className?: string;
}

const DEFAULT_TABS: TabItem[] = [
  {
    id: "preview",
    label: "Overview",
    content: (
      <div className="space-y-1.5">
        <div className="text-xs font-semibold text-black dark:text-white">
          Shared-Element Sliding Indicator
        </div>
        <p className="text-xs leading-relaxed text-neutral-500 dark:text-neutral-400">
          The active pill glides smoothly between tabs using Framer Motion
          layoutId springs with zero layout shift.
        </p>
      </div>
    ),
  },
  {
    id: "metrics",
    label: "Metrics",
    badge: "99.9%",
    content: (
      <div className="grid grid-cols-2 gap-3">
        <div className="rounded-xl border border-neutral-200 p-3 dark:border-[#222222]">
          <div className="font-mono text-[10px] text-neutral-400">FRAME BUDGET</div>
          <div className="mt-1 font-mono text-sm font-semibold text-black dark:text-white">
            &lt; 1.2ms
          </div>
        </div>
        <div className="rounded-xl border border-neutral-200 p-3 dark:border-[#222222]">
          <div className="font-mono text-[10px] text-neutral-400">BUNDLE SIZE</div>
          <div className="mt-1 font-mono text-sm font-semibold text-black dark:text-white">
            1.8 kB
          </div>
        </div>
      </div>
    ),
  },
  {
    id: "settings",
    label: "Settings",
    content: (
      <div className="space-y-1.5">
        <div className="text-xs font-semibold text-black dark:text-white">
          Keyboard Accessible
        </div>
        <p className="text-xs leading-relaxed text-neutral-500 dark:text-neutral-400">
          Use Left, Right, Home, and End keys to cycle through tabs with full
          WAI-ARIA tablist focus management.
        </p>
      </div>
    ),
  },
];

export function AnimatedTabs({
  tabs = DEFAULT_TABS,
  defaultTabId,
  onChange,
  className,
}: AnimatedTabsProps) {
  const shouldReduceMotion = useReducedMotion();
  const instanceId = useId();
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const [activeId, setActiveId] = useState<string>(
    defaultTabId || tabs[0]?.id || ""
  );

  const activeTab = tabs.find((t) => t.id === activeId) || tabs[0];

  const handleSelect = (id: string, focusIndex?: number) => {
    setActiveId(id);
    onChange?.(id);
    if (focusIndex !== undefined) {
      tabRefs.current[focusIndex]?.focus();
    }
  };

  const handleKeyDown = (
    e: React.KeyboardEvent<HTMLButtonElement>,
    idx: number
  ) => {
    if (e.key === "ArrowRight") {
      e.preventDefault();
      const nextIdx = (idx + 1) % tabs.length;
      const next = tabs[nextIdx];
      if (next) handleSelect(next.id, nextIdx);
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      const prevIdx = (idx - 1 + tabs.length) % tabs.length;
      const prev = tabs[prevIdx];
      if (prev) handleSelect(prev.id, prevIdx);
    } else if (e.key === "Home") {
      e.preventDefault();
      if (tabs[0]) handleSelect(tabs[0].id, 0);
    } else if (e.key === "End") {
      e.preventDefault();
      const lastIdx = tabs.length - 1;
      if (tabs[lastIdx]) handleSelect(tabs[lastIdx].id, lastIdx);
    }
  };

  return (
    <div className={cn("w-full max-w-md", className)}>
      {/* Tab List */}
      <div
        role="tablist"
        aria-label="Content tabs"
        className="inline-flex w-full items-center gap-1 rounded-xl border border-neutral-200 bg-neutral-100/80 p-1 dark:border-[#222222] dark:bg-[#0C0C0C]"
      >
        {tabs.map((tab, idx) => {
          const isActive = tab.id === activeId;
          return (
            <button
              key={tab.id}
              ref={(el) => {
                tabRefs.current[idx] = el;
              }}
              type="button"
              role="tab"
              tabIndex={isActive ? 0 : -1}
              aria-selected={isActive}
              onClick={() => handleSelect(tab.id)}
              onKeyDown={(e) => handleKeyDown(e, idx)}
              className={cn(
                "relative flex flex-1 cursor-pointer items-center justify-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black dark:focus-visible:ring-white",
                isActive
                  ? "text-white dark:text-black"
                  : "text-neutral-600 hover:text-black dark:text-neutral-400 dark:hover:text-white"
              )}
            >
              {isActive && (
                <motion.span
                  layoutId={`tab-pill-${instanceId}`}
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { type: "spring", stiffness: 420, damping: 32 }
                  }
                  className="absolute inset-0 rounded-lg bg-black shadow-xs dark:bg-white"
                />
              )}
              <span className="relative z-10">{tab.label}</span>
              {tab.badge !== undefined && (
                <span
                  className={cn(
                    "relative z-10 rounded px-1 py-0.2 font-mono text-[10px]",
                    isActive
                      ? "bg-white/20 text-white dark:bg-black/15 dark:text-black"
                      : "bg-neutral-200/80 text-neutral-600 dark:bg-[#1A1A1A] dark:text-neutral-400"
                  )}
                >
                  {tab.badge}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Tab Panel */}
      <div
        role="tabpanel"
        className="mt-3 overflow-hidden rounded-2xl border border-neutral-200 bg-white p-5 dark:border-[#222222] dark:bg-[#0A0A0A]"
      >
        <AnimatePresence mode="wait" initial={false}>
          <motion.div
            key={activeTab?.id}
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
            transition={{ duration: shouldReduceMotion ? 0 : 0.16 }}
          >
            {activeTab?.content}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

export default AnimatedTabs;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import React, { useState, useRef, useEffect } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  Copy,
  Share2,
  Pin,
  FolderInput,
  Trash2,
  MoreHorizontal,
  Check,
} from "lucide-react";
import { cn } from "@/lib/utils";

export interface ContextMenuItem {
  id: string;
  label: string;
  shortcut?: string;
  icon?: React.ReactNode;
  destructive?: boolean;
  onSelect?: () => void;
}

export interface ContextMenuGroup {
  id: string;
  items: ContextMenuItem[];
}

export interface AppleContextMenuProps {
  /** Grouped menu items separated by hairline dividers */
  groups?: ContextMenuGroup[];
  /** Label shown on the trigger button */
  triggerLabel?: string;
  /** Initial open state for uncontrolled mode. Default: false */
  defaultOpen?: boolean;
  /** Callback fired when any menu item is clicked */
  onSelect?: (item: ContextMenuItem) => void;
  className?: string;
}

const DEFAULT_GROUPS: ContextMenuGroup[] = [
  {
    id: "primary",
    items: [
      {
        id: "copy",
        label: "Copy Component Link",
        shortcut: "⌘C",
        icon: <Copy className="h-3.5 w-3.5" />,
      },
      {
        id: "share",
        label: "Share Preview...",
        shortcut: "⇧⌘S",
        icon: <Share2 className="h-3.5 w-3.5" />,
      },
      {
        id: "pin",
        label: "Pin to Workspace",
        shortcut: "⌘P",
        icon: <Pin className="h-3.5 w-3.5" />,
      },
    ],
  },
  {
    id: "organize",
    items: [
      {
        id: "move",
        label: "Move to Collection",
        icon: <FolderInput className="h-3.5 w-3.5" />,
      },
    ],
  },
  {
    id: "danger",
    items: [
      {
        id: "delete",
        label: "Delete Component",
        shortcut: "⌘⌫",
        icon: <Trash2 className="h-3.5 w-3.5" />,
        destructive: true,
      },
    ],
  },
];

export function AppleContextMenu({
  groups = DEFAULT_GROUPS,
  triggerLabel = "Actions Menu",
  defaultOpen = false,
  onSelect,
  className,
}: AppleContextMenuProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const containerRef = useRef<HTMLDivElement>(null);

  const [open, setOpen] = useState(defaultOpen);
  const [lastAction, setLastAction] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    const handleOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handleOutside);
    window.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleOutside);
      window.removeEventListener("keydown", handleEscape);
    };
  }, [open]);

  const handleSelect = (item: ContextMenuItem) => {
    item.onSelect?.();
    onSelect?.(item);
    setLastAction(item.label);
    setOpen(false);
  };

  return (
    <div
      ref={containerRef}
      onContextMenu={(e) => {
        e.preventDefault();
        setOpen(true);
      }}
      className={cn("relative inline-flex flex-col items-center", className)}
    >
      {/* Trigger Bar */}
      <div className="flex items-center gap-2.5">
        <button
          type="button"
          aria-haspopup="menu"
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
          className={cn(
            "inline-flex h-10 items-center gap-2 rounded-2xl border px-4 text-xs font-semibold shadow-2xs transition-all active:scale-95",
            open
              ? "border-neutral-900 bg-neutral-900 text-white dark:border-white dark:bg-white dark:text-black"
              : "border-neutral-200 bg-white text-neutral-900 hover:border-neutral-900 dark:border-neutral-800 dark:bg-[#0A0A0A] dark:text-white dark:hover:border-white"
          )}
        >
          <span>{triggerLabel}</span>
          <MoreHorizontal className="h-4 w-4" />
        </button>

        {lastAction && (
          <span className="inline-flex items-center gap-1 text-[11px] text-neutral-500 dark:text-neutral-400">
            <Check className="h-3 w-3 text-neutral-900 dark:text-white" />
            {lastAction}
          </span>
        )}
      </div>

      {/* Frosted Blurred Context Popover with Small Arrow */}
      <AnimatePresence>
        {open && (
          <motion.div
            role="menu"
            aria-label={triggerLabel}
            initial={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, scale: 0.92, y: -6 }
            }
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={
              shouldReduceMotion
                ? { opacity: 0 }
                : { opacity: 0, scale: 0.94, y: -4 }
            }
            transition={{ type: "spring", stiffness: 440, damping: 28 }}
            style={{ originY: 0 }}
            className="absolute top-[calc(100%+12px)] z-50 w-60 rounded-2xl border border-neutral-200/90 bg-white/90 p-1.5 shadow-2xl backdrop-blur-xl dark:border-neutral-800/90 dark:bg-[#121212]/90"
          >
            {/* Small Top Arrow Caret */}
            <div
              aria-hidden="true"
              className="absolute -top-1.5 left-1/2 h-3 w-3 -translate-x-1/2 rotate-45 border-l border-t border-neutral-200/90 bg-white/90 dark:border-neutral-800/90 dark:bg-[#121212]/90"
            />

            {/* Grouped Actions */}
            <div className="relative z-10 divide-y divide-neutral-200/75 dark:divide-neutral-800/80">
              {groups.map((group) => (
                <div key={group.id} className="py-1 first:pt-0 last:pb-0">
                  {group.items.map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      role="menuitem"
                      onClick={() => handleSelect(item)}
                      className={cn(
                        "flex w-full items-center justify-between rounded-xl px-3 py-2 text-left text-xs font-medium transition-colors",
                        item.destructive
                          ? "text-red-600 hover:bg-red-500/10 dark:text-red-400 dark:hover:bg-red-500/15"
                          : "text-neutral-800 hover:bg-neutral-100/90 dark:text-neutral-200 dark:hover:bg-neutral-800/70"
                      )}
                    >
                      <span className="flex items-center gap-2.5">
                        <span
                          className={cn(
                            item.destructive
                              ? "text-red-500 dark:text-red-400"
                              : "text-neutral-500 dark:text-neutral-400"
                          )}
                        >
                          {item.icon}
                        </span>
                        <span>{item.label}</span>
                      </span>

                      {item.shortcut && (
                        <kbd
                          className={cn(
                            "font-mono text-[10px]",
                            item.destructive
                              ? "text-red-400 dark:text-red-500/80"
                              : "text-neutral-400 dark:text-neutral-500"
                          )}
                        >
                          {item.shortcut}
                        </kbd>
                      )}
                    </button>
                  ))}
                </div>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

