  color?: string;
  /** Fall speed multiplier */
  speed?: number;
  /** Stream density multiplier (0.3 to 2.0) */
  density?: number;
  /** Glyph character set */
  charset?: "katakana" | "binary" | "hex";
  /** Font size in pixels */
  fontSize?: number;
  /** Optional overlay content */
  children?: React.ReactNode;
